// Root observation transport: only original tiny-skia executes shader preparation.
use serde::{Deserialize,Serialize};use std::io::{self,Read};
static WARNINGS:std::sync::Mutex<Vec<String>>=std::sync::Mutex::new(Vec::new());struct Observer;static OBSERVER:Observer=Observer;
impl log::Log for Observer{fn enabled(&self,m:&log::Metadata)->bool{m.level()<=log::Level::Warn}fn log(&self,r:&log::Record){if self.enabled(r.metadata()){WARNINGS.lock().unwrap().push(r.args().to_string());}}fn flush(&self){}}
#[derive(Deserialize,Serialize)]struct Input{width:u32,height:u32,spread:u8,quality:u8,opacity:u32,transform:[u32;6],transforms:Vec<[u32;6]>,opacities:Vec<u32>,color_space:u8,prefix:usize,sentinel:bool,force:bool}
#[derive(Serialize)]struct Output{input:Input,result:(String,Vec<u32>,Vec<String>,Vec<Vec<u32>>,bool),warnings:Vec<String>}
fn main(){log::set_logger(&OBSERVER).unwrap();log::set_max_level(log::LevelFilter::Warn);std::panic::set_hook(Box::new(|_|{}));let mut text=String::new();io::stdin().read_to_string(&mut text).unwrap();let inputs:Vec<Input>=serde_json::from_str(&text).unwrap();let out:Vec<_>=inputs.into_iter().map(|input|{let result=tiny_skia::folia_pattern_producer(input.width,input.height,input.spread,input.quality,input.opacity,input.transform,&input.transforms,&input.opacities,input.color_space,input.prefix,input.sentinel,input.force);let warnings=std::mem::take(&mut*WARNINGS.lock().unwrap());Output{input,result,warnings}}).collect();println!("{}",serde_json::to_string(&out).unwrap());}
